/** Complete editors for the remaining owned template families. */
namespace AxisCNC\Suite;
defined('ABSPATH') || exit;

// Preserve the existing RFQ consent copy stored by its historical form schema.
// Fluent Forms now reads html_codes; an intentional empty value stays empty.
add_filter('fluentform/rendering_field_data_custom_html', static function($data, $form) {
    if ((int)($form->id ?? 0) === 3 && !array_key_exists('html_codes', $data['settings'] ?? []) && isset($data['settings']['html'])) {
        $data['settings']['html_codes'] = $data['settings']['html'];
    }
    return $data;
}, 10, 2);
